"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["89857"],{9854(e){e.exports=JSON.parse('{"id":"FIN-344","slug":"universal-bank","term":"Universal Bank","also_known_as":[],"difficulty":"Intermediate","definition":"A universal bank is a bank that offers a wide range of financial services under one roof, including retail banking, commercial banking, investment banking and often insurance and asset management.","explanation":["Rather than specialising, a universal bank serves almost every type of customer and need. It may provide current accounts and mortgages to individuals, loans and payments to businesses, advice on mergers and share issues to large companies, trading in financial markets and investment management for wealthy clients.","Many of the largest banks in Europe and elsewhere operate as universal banks.","Supporters argue that the model brings benefits: customers can access many services from one institution, the bank can spread risks across different businesses and it can cross-sell products. For example, a business customer with a commercial loan may also use the bank\'s investment banking division when it later goes public.","Critics argue that combining risky trading and investment banking with ordinary deposit-taking can put depositors and taxpayers at risk if the riskier activities suffer heavy losses. After the 2008 financial crisis, some countries introduced rules requiring large banks to separate or ring-fence their retail operations from investment banking activities."],"note":"","total":1500,"prev":{"slug":"unitranche-debt","term":"Unitranche Debt"},"next":{"slug":"universal-life-insurance","term":"Universal Life Insurance"}}')}}]);